package com.healindicators;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Heal Indicators+",
	description = "Displays heal splats whenever your visible HP increases",
	tags = {"healing", "hitsplat", "food", "blood", "hitpoints"}
)
public class HealIndicatorsPlugin extends Plugin
{
	static final int SPLAT_MAX_VALUE = 99;
	private static final int MAX_SPLATS_PER_TICK = 4;
	private static final int STARTUP_WARMUP_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HealIndicatorsOverlay overlay;

	@Inject
	private HealIndicatorsConfig config;

	@Inject
	private ConfigManager configManager;

	private final List<HealSplatEntry> activeSplats = new ArrayList<>();
	private Integer lastVisibleHp;
	private Integer lastVisiblePrayer;
	private int lastProcessedTick = -1;
	private int warmupTicksRemaining = 0;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		resetState(true);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		resetState(true);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"healindicators".equals(event.getGroup()))
		{
			return;
		}

		if ("testHealSplatTrigger".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			addTestSplat(SplatType.HEAL);
			configManager.setConfiguration("healindicators", "testHealSplatTrigger", false);
			return;
		}

		if ("testPrayerSplatTrigger".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			addTestSplat(SplatType.PRAYER);
			configManager.setConfiguration("healindicators", "testPrayerSplatTrigger", false);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			resetState(false);
			return;
		}

		resetState(true);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}

		final int currentTick = client.getTickCount();
		if (currentTick == lastProcessedTick)
		{
			return;
		}
		lastProcessedTick = currentTick;

		final int currentVisibleHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
		final int currentVisiblePrayer = client.getBoostedSkillLevel(Skill.PRAYER);
		if (lastVisibleHp == null)
		{
			lastVisibleHp = currentVisibleHp;
			lastVisiblePrayer = currentVisiblePrayer;
			return;
		}

		if (warmupTicksRemaining > 0)
		{
			warmupTicksRemaining--;
			lastVisibleHp = currentVisibleHp;
			lastVisiblePrayer = currentVisiblePrayer;
			pruneExpiredSplats();
			return;
		}

		final int healDelta = currentVisibleHp - lastVisibleHp;
		if (healDelta > 0 && config.enableHealSplats())
		{
			final boolean isRegenHeal = isNaturalHpRegeneration(healDelta);
			if (!(isRegenHeal && !config.showHealRegenerationSplats()))
			{
				addSplats(healDelta, SplatType.HEAL, config.splatDurationCycles());
			}
		}

		final int prayerDelta = currentVisiblePrayer - lastVisiblePrayer;
		if (prayerDelta > 0 && config.enablePrayerSplats())
		{
			final boolean isPrayerRegen = isPrayerRegenerationPotionTick(prayerDelta);
			if (!(isPrayerRegen && !config.showPrayerRegenerationSplats()))
			{
				addSplats(prayerDelta, SplatType.PRAYER, config.splatDurationCycles());
			}
		}

		lastVisibleHp = currentVisibleHp;
		lastVisiblePrayer = currentVisiblePrayer;
		pruneExpiredSplats();
	}

	List<HealSplatEntry> getActiveSplats()
	{
		return Collections.unmodifiableList(activeSplats);
	}

	private void addTestSplat(SplatType type)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}

		final int amount = ThreadLocalRandom.current().nextInt(1, 100);
		addSplats(amount, type, config.splatDurationCycles());
	}

	private boolean isNaturalHpRegeneration(int healDelta)
	{
		return healDelta == 1;
	}

	private boolean isPrayerRegenerationPotionTick(int prayerDelta)
	{
		return prayerDelta == 1;
	}

	private void addSplats(int totalAmount, SplatType type, int lifetimeCycles)
	{
		int remaining = totalAmount;
		int emitted = 0;
		final int cap = MAX_SPLATS_PER_TICK;
		final int startCycle = client.getGameCycle();
		final int effectiveLifetime = Math.max(1, lifetimeCycles);

		while (remaining > 0 && emitted < cap)
		{
			final int splatAmount = Math.min(remaining, SPLAT_MAX_VALUE);
			activeSplats.add(new HealSplatEntry(splatAmount, startCycle, startCycle + effectiveLifetime, type));
			remaining -= splatAmount;
			emitted++;
		}

		// Preserve total heal information if safety cap is reached.
		if (remaining > 0 && !activeSplats.isEmpty())
		{
			HealSplatEntry last = activeSplats.get(activeSplats.size() - 1);
			last.setAmount(Math.min(999, last.getAmount() + remaining));
		}
	}

	private void pruneExpiredSplats()
	{
		final int gameCycle = client.getGameCycle();
		activeSplats.removeIf(splat -> splat.getExpiresOnGameCycle() <= gameCycle);
	}

	private void resetState(boolean clearSplats)
	{
		lastVisibleHp = null;
		lastVisiblePrayer = null;
		lastProcessedTick = -1;
		warmupTicksRemaining = STARTUP_WARMUP_TICKS;

		if (clearSplats)
		{
			activeSplats.clear();
		}
	}

	@Provides
	HealIndicatorsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HealIndicatorsConfig.class);
	}

	static class HealSplatEntry
	{
		private int amount;
		private final int spawnedOnGameCycle;
		private final int expiresOnGameCycle;
		private final SplatType type;

		HealSplatEntry(int amount, int spawnedOnGameCycle, int expiresOnGameCycle, SplatType type)
		{
			this.amount = amount;
			this.spawnedOnGameCycle = spawnedOnGameCycle;
			this.expiresOnGameCycle = expiresOnGameCycle;
			this.type = type;
		}

		int getAmount()
		{
			return amount;
		}

		void setAmount(int amount)
		{
			this.amount = amount;
		}

		int getSpawnedOnGameCycle()
		{
			return spawnedOnGameCycle;
		}

		int getExpiresOnGameCycle()
		{
			return expiresOnGameCycle;
		}

		SplatType getType()
		{
			return type;
		}
	}

	enum SplatType
	{
		HEAL,
		PRAYER
	}
}

package com.healindicators;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("healindicators")
public interface HealIndicatorsConfig extends Config
{
	enum SplatAnchor
	{
		ABOVE_HEAD("Head"),
		BODY("Body");

		private final String displayName;

		SplatAnchor(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	@ConfigSection(
		name = "Heal Splats",
		description = "Settings for hitpoint heal splats",
		position = 4,
		closedByDefault = false
	)
	String healSection = "healSection";

	@ConfigSection(
		name = "Prayer Splats",
		description = "Settings for prayer restore splats",
		position = 5,
		closedByDefault = false
	)
	String prayerSection = "prayerSection";

	@ConfigItem(
		keyName = "riseEffectEnabled",
		name = "Rise effect",
		description = "Make both heal and prayer splats rise upward over time",
		position = 0
	)
	default boolean riseEffectEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "splatAnchor",
		name = "Position",
		description = "Where all splats render around the player",
		position = 1
	)
	default SplatAnchor splatAnchor()
	{
		return SplatAnchor.BODY;
	}

	@Range(min = 10, max = 120)
	@ConfigItem(
		keyName = "splatDurationCycles",
		name = "Splat duration (cycles)",
		description = "How long all splats stay visible",
		position = 2
	)
	default int splatDurationCycles()
	{
		return 45;
	}

	@ConfigItem(
		keyName = "textOutlineEnabled",
		name = "Text outline",
		description = "Draw a black outline around splat numbers",
		position = 3
	)
	default boolean textOutlineEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableHealSplats",
		name = "Enable heal splats",
		description = "Show splats when your visible hitpoints increase",
		position = 0,
		section = healSection
	)
	default boolean enableHealSplats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHealRegenerationSplats",
		name = "Show regeneration",
		description = "Show heal splats for passive healing",
		position = 1,
		section = healSection
	)
	default boolean showHealRegenerationSplats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "healSplatColor",
		name = "Splat color",
		description = "Tint color applied to the heal splat icon",
		position = 2,
		section = healSection
	)
	default Color healSplatColor()
	{
		return new Color(250, 0, 255);
	}

	@Range(min = 50, max = 200)
	@ConfigItem(
		keyName = "healIconSizePercent",
		name = "Splat size (%)",
		description = "Scale of the heal icon",
		position = 3,
		section = healSection
	)
	default int healIconSizePercent()
	{
		return 100;
	}

	@Range(min = 8, max = 24)
	@ConfigItem(
		keyName = "healTextFontSize",
		name = "Font size",
		description = "Number size for heal splats",
		position = 4,
		section = healSection
	)
	default int healTextFontSize()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "testHealSplatTrigger",
		name = "Test heal splat",
		description = "Toggle to spawn a random heal test splat",
		position = 5,
		section = healSection
	)
	default boolean testHealSplatTrigger()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enablePrayerSplats",
		name = "Enable prayer splats",
		description = "Show splats when your visible prayer points increase",
		position = 0,
		section = prayerSection
	)
	default boolean enablePrayerSplats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPrayerRegenerationSplats",
		name = "Show regeneration",
		description = "Show prayer splats for prayer regeneration",
		position = 1,
		section = prayerSection
	)
	default boolean showPrayerRegenerationSplats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "prayerSplatColor",
		name = "Splat color",
		description = "Tint color applied to the prayer splat icon",
		position = 2,
		section = prayerSection
	)
	default Color prayerSplatColor()
	{
		return new Color(255, 255, 255);
	}

	@Range(min = 50, max = 200)
	@ConfigItem(
		keyName = "prayerIconSizePercent",
		name = "Splat size (%)",
		description = "Scale of the prayer icon",
		position = 3,
		section = prayerSection
	)
	default int prayerIconSizePercent()
	{
		return 100;
	}

	@Range(min = 8, max = 24)
	@ConfigItem(
		keyName = "prayerTextFontSize",
		name = "Font size",
		description = "Number size for prayer splats",
		position = 4,
		section = prayerSection
	)
	default int prayerTextFontSize()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "testPrayerSplatTrigger",
		name = "Test prayer splat",
		description = "Toggle to spawn a random prayer test splat",
		position = 5,
		section = prayerSection
	)
	default boolean testPrayerSplatTrigger()
	{
		return false;
	}
}

package com.healindicators;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.font.FontRenderContext;
import java.awt.font.GlyphVector;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.ImageUtil;

public class HealIndicatorsOverlay extends Overlay
{
	private static final Class<?> PLUGIN_CLASS = HealIndicatorsOverlay.class;
	private static final int FADE_OUT_CYCLES = 8;
	private static final int RISE_PIXELS = 20;
	private static final int SPLAT_BASELINE_Y_OFFSET = 40;
	private static final BufferedImage HEAL_SPLAT_ICON = ImageUtil.loadImageResource(PLUGIN_CLASS, "/heal_splat.png");
	private static final BufferedImage PRAYER_SPLAT_ICON = ImageUtil.loadImageResource(PLUGIN_CLASS, "/prayer_splat.png");
	private static final String ANCHOR_TEXT = "99";
	private static final float LUMA_R = 0.2126f;
	private static final float LUMA_G = 0.7152f;
	private static final float LUMA_B = 0.0722f;

	private Color cachedHealColor;
	private BufferedImage cachedHealTintedIcon;
	private int cachedHealIconSizePercent;
	private Color cachedPrayerColor;
	private BufferedImage cachedPrayerTintedIcon;
	private int cachedPrayerIconSizePercent;
	private final Map<HealIndicatorsPlugin.HealSplatEntry, ClusterAssignment> clusterAssignments = new IdentityHashMap<>();

	@Inject
	private HealIndicatorsPlugin plugin;

	@Inject
	private HealIndicatorsConfig config;

	@Inject
	private Client client;

	@Inject
	HealIndicatorsOverlay()
	{
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableHealSplats() && !config.enablePrayerSplats())
		{
			return null;
		}

		final Actor localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}

		final List<HealIndicatorsPlugin.HealSplatEntry> splats = plugin.getActiveSplats();
		if (splats.isEmpty())
		{
			return null;
		}

		final Font previousFont = graphics.getFont();
		Font baseFont = FontManager.getRunescapeSmallFont();

		final int currentCycle = client.getGameCycle();
		final Set<HealIndicatorsPlugin.HealSplatEntry> currentlyRendered = new HashSet<>();
		final Map<HealIndicatorsConfig.SplatAnchor, Set<Integer>> usedSlotsByAnchor =
			new EnumMap<>(HealIndicatorsConfig.SplatAnchor.class);

		for (int i = 0; i < splats.size(); i++)
		{
			HealIndicatorsPlugin.HealSplatEntry splat = splats.get(i);
			if (splat.getType() == HealIndicatorsPlugin.SplatType.HEAL && !config.enableHealSplats())
			{
				continue;
			}
			if (splat.getType() == HealIndicatorsPlugin.SplatType.PRAYER && !config.enablePrayerSplats())
			{
				continue;
			}

			final int remaining = splat.getExpiresOnGameCycle() - currentCycle;
			if (remaining <= 0)
			{
				continue;
			}

			final float fontSize = splat.getType() == HealIndicatorsPlugin.SplatType.PRAYER
				? config.prayerTextFontSize()
				: config.healTextFontSize();
			graphics.setFont(baseFont.deriveFont(fontSize));

			final String text = Integer.toString(splat.getAmount());
			final BufferedImage splatIcon = getTintedIcon(splat.getType());
			final Point anchor = resolveAnchor(graphics, localPlayer, splat.getType(), splatIcon);
			if (anchor == null)
			{
				continue;
			}

			final int totalLifetime = Math.max(1, splat.getExpiresOnGameCycle() - splat.getSpawnedOnGameCycle());
			final double progress = 1.0 - (remaining / (double) totalLifetime);
			final boolean riseEnabled = config.riseEffectEnabled();
			final int rise = riseEnabled ? (int) Math.round(progress * RISE_PIXELS) : 0;
			final float alpha = remaining < FADE_OUT_CYCLES ? (remaining / (float) FADE_OUT_CYCLES) : 1.0f;
			final HealIndicatorsConfig.SplatAnchor configuredAnchor = config.splatAnchor();
			final int slot = resolveClusterSlot(splat, configuredAnchor, usedSlotsByAnchor);
			currentlyRendered.add(splat);

			final int x = anchor.getX() + clusterXOffset(slot) - 6;
			final int y = anchor.getY() + SPLAT_BASELINE_Y_OFFSET + clusterYOffset(slot) - rise;
			drawSplat(graphics, x, y, text, alpha, splatIcon, config.textOutlineEnabled());
		}

		clusterAssignments.entrySet().removeIf(entry -> !currentlyRendered.contains(entry.getKey()));

		graphics.setFont(previousFont);
		return null;
	}

	private int resolveClusterSlot(
		HealIndicatorsPlugin.HealSplatEntry splat,
		HealIndicatorsConfig.SplatAnchor anchor,
		Map<HealIndicatorsConfig.SplatAnchor, Set<Integer>> usedSlotsByAnchor)
	{
		final Set<Integer> usedSlots = usedSlotsByAnchor.computeIfAbsent(anchor, key -> new HashSet<>());
		ClusterAssignment assignment = clusterAssignments.get(splat);
		if (assignment == null || assignment.anchor != anchor || usedSlots.contains(assignment.slot))
		{
			final int slot = firstAvailableSlot(usedSlots);
			assignment = new ClusterAssignment(anchor, slot);
			clusterAssignments.put(splat, assignment);
		}
		usedSlots.add(assignment.slot);
		return assignment.slot;
	}

	private static int firstAvailableSlot(Set<Integer> usedSlots)
	{
		int slot = 0;
		while (usedSlots.contains(slot))
		{
			slot++;
		}
		return slot;
	}

	private static int clusterXOffset(int index)
	{
		switch (index)
		{
			case 0:
			case 5:
				return 0;
			case 1:
			case 3:
			case 6:
				return -20;
			case 2:
			case 4:
			case 7:
				return 20;
			default:
				return 0;
		}
	}

	private static int clusterYOffset(int index)
	{
		switch (index)
		{
			case 1:
			case 2:
				return -15;
			case 0:
				return 0;
			case 3:
			case 4:
				return 15;
			case 5:
				return 30;
			case 6:
			case 7:
				return 45;
			default:
				return -30;
		}
	}

	private static final class ClusterAssignment
	{
		private final HealIndicatorsConfig.SplatAnchor anchor;
		private final int slot;

		private ClusterAssignment(HealIndicatorsConfig.SplatAnchor anchor, int slot)
		{
			this.anchor = anchor;
			this.slot = slot;
		}
	}

	private static void drawSplat(
		Graphics2D graphics,
		int iconX,
		int iconY,
		String text,
		float alpha,
		BufferedImage icon,
		boolean textOutlineEnabled)
	{
		if (icon == null)
		{
			return;
		}

		// Center the actual rendered pixels of the text within the icon. Font
		// metrics (stringWidth/ascent) include per-glyph side bearings and
		// font-wide constants that shift different numbers inconsistently.
		final FontRenderContext frc = graphics.getFontRenderContext();
		final GlyphVector glyphVector = graphics.getFont().createGlyphVector(frc, text);
		final Rectangle textBounds = glyphVector.getPixelBounds(frc, 0, 0);
		final int textX = iconX + ((icon.getWidth() - textBounds.width) / 2) - textBounds.x;
		final int textY = iconY + ((icon.getHeight() - textBounds.height) / 2) - textBounds.y;

		final Composite previousComposite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		graphics.drawImage(icon, iconX, iconY, null);
		if (textOutlineEnabled)
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, textX - 1, textY);
			graphics.drawString(text, textX + 1, textY);
			graphics.drawString(text, textX, textY - 1);
			graphics.drawString(text, textX, textY + 1);
			graphics.drawString(text, textX - 1, textY - 1);
			graphics.drawString(text, textX + 1, textY - 1);
			graphics.drawString(text, textX - 1, textY + 1);
			graphics.drawString(text, textX + 1, textY + 1);
		}
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, textX, textY);
		graphics.setComposite(previousComposite);
	}

	private BufferedImage getTintedIcon(HealIndicatorsPlugin.SplatType type)
	{
		if (type == HealIndicatorsPlugin.SplatType.PRAYER)
		{
			final Color target = config.prayerSplatColor();
			final int sizePercent = config.prayerIconSizePercent();
			if (!target.equals(cachedPrayerColor) || cachedPrayerTintedIcon == null || cachedPrayerIconSizePercent != sizePercent)
			{
				cachedPrayerColor = target;
				cachedPrayerIconSizePercent = sizePercent;
				BufferedImage tinted = tintIconLuminance(PRAYER_SPLAT_ICON, target);
				cachedPrayerTintedIcon = scaleIcon(tinted, sizePercent);
			}
			return cachedPrayerTintedIcon;
		}

		final Color target = config.healSplatColor();
		final int sizePercent = config.healIconSizePercent();
		if (!target.equals(cachedHealColor) || cachedHealTintedIcon == null || cachedHealIconSizePercent != sizePercent)
		{
			cachedHealColor = target;
			cachedHealIconSizePercent = sizePercent;
			BufferedImage tinted = tintIconLuminance(HEAL_SPLAT_ICON, target);
			cachedHealTintedIcon = scaleIcon(tinted, sizePercent);
		}
		return cachedHealTintedIcon;
	}

	private Point resolveAnchor(Graphics2D graphics, Actor localPlayer, HealIndicatorsPlugin.SplatType type, BufferedImage icon)
	{
		HealIndicatorsConfig.SplatAnchor anchor = config.splatAnchor();
		int zOffset = anchor == HealIndicatorsConfig.SplatAnchor.ABOVE_HEAD
			? localPlayer.getLogicalHeight() + 30
			: Math.max(0, (localPlayer.getLogicalHeight() / 2) + 15);

		if (icon != null)
		{
			return localPlayer.getCanvasImageLocation(icon, zOffset);
		}

		return localPlayer.getCanvasTextLocation(graphics, ANCHOR_TEXT, zOffset);
	}

	private static BufferedImage tintIconLuminance(BufferedImage source, Color tint)
	{
		if (source == null)
		{
			return null;
		}

		BufferedImage tinted = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
		final float tintR = tint.getRed() / 255.0f;
		final float tintG = tint.getGreen() / 255.0f;
		final float tintB = tint.getBlue() / 255.0f;

		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				final int argb = source.getRGB(x, y);
				final int alpha = (argb >>> 24) & 0xFF;
				if (alpha == 0)
				{
					tinted.setRGB(x, y, 0);
					continue;
				}

				final int red = (argb >>> 16) & 0xFF;
				final int green = (argb >>> 8) & 0xFF;
				final int blue = argb & 0xFF;
				final float luminance = ((LUMA_R * red) + (LUMA_G * green) + (LUMA_B * blue)) / 255.0f;

				final int outR = clamp255(Math.round(255.0f * tintR * luminance));
				final int outG = clamp255(Math.round(255.0f * tintG * luminance));
				final int outB = clamp255(Math.round(255.0f * tintB * luminance));
				final int outArgb = (alpha << 24) | (outR << 16) | (outG << 8) | outB;
				tinted.setRGB(x, y, outArgb);
			}
		}

		return tinted;
	}

	private static int clamp255(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

	private static BufferedImage scaleIcon(BufferedImage source, int sizePercent)
	{
		if (source == null)
		{
			return null;
		}
		if (sizePercent == 100)
		{
			return source;
		}

		int width = Math.max(1, Math.round(source.getWidth() * (sizePercent / 100.0f)));
		int height = Math.max(1, Math.round(source.getHeight() * (sizePercent / 100.0f)));
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = scaled.createGraphics();
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g2.drawImage(source, 0, 0, width, height, null);
		g2.dispose();
		return scaled;
	}
}
